catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

   //Type appropriate comment here, and begin script below
    // 初期化
    g_form.clearValue('u_l1_approver');
    g_form.setMandatory('u_l1_approver', false);
    g_form.setDisplay('u_l1_approver', false);
	g_form.clearValue('u_l2_approver_group');
    g_form.setMandatory('u_l2_approver_group', false);
    g_form.setDisplay('u_l2_approver_group', false);

	if (g_form.getValue('amount') =='b') {
    g_form.setMandatory('u_l1_approver', true); //必須
    g_form.setDisplay('u_l1_approver', true); //表示
	g_form.setvalue('u_l1_approver','Jess Assad');
    g_form.setMandatory('u_l2_approver_group', true); //必須
    g_form.setDisplay('u_l2_approver_group', true); //表示
	g_form.setvalue('u_l2_approver_group','Analytics Settings Managers');
	} else {
	g_form.setMandatory('u_l1_approver', true); //必須
    g_form.setDisplay('u_l1_approver', true); //表示
	g_form.setvalue('u_l1_approver','Jess Assad');	
	}


}
